from tornado.testing import gen_test

from tests.base import FilterTestCase


class FakeSmallEngine:
    @property
    def size(self):
        return (80, 50)

    def get_orientation(self):
        return 1


class NoUpscaleFitInCanvasTestCase(FilterTestCase):
    @gen_test
    async def test_no_upscale_keeps_fit_in_canvas_size(self):
        def config_context(context):
            context.request.fit_in = True
            context.request.width = 300
            context.request.height = 300
            context.request.engine = FakeSmallEngine()

        fltr = self.get_filter(
            "thumbor.filters.no_upscale",
            "no_upscale()",
            config_context=config_context,
        )

        await fltr.run()

        assert self.context.request.width == 300
        assert self.context.request.height == 300

